export default "/* mail.css — domain residue for com.ikenga.mail.\n *\n * Only mail-local classes live here (.mail-row*, .reader-*, .thread-*, .pane-split).\n * Kit primitives (.frame*, .ip-*, .dense-row*, .btn*, .tag, .chip, .badge,\n * .atelier-state*, .avatar*, .chat-msg*, .nav-group*, .nav-item*, etc.) are\n * consumed from app-kit-css.js — never re-derived here.\n *\n * Inject order: tokens-css → app-kit-css → mail-css (this file).\n * Scoped under data-workspace=\"mail\" where needed (amber tint).\n */\n\n/* ── Reduced motion gate ── */\n@media (prefers-reduced-motion: reduce) {\n  .mail-row { transition: none; }\n}\n\n/* ── Two-column split ── */\n/* mail-local — NOT .ip-split (the reading pane is richer than a pipeline detail) */\n.pane-split {\n  display: grid;\n  grid-template-columns: 380px 1fr;\n  overflow: hidden;\n  height: 100%;\n}\n\n/* ── Mail list column ── */\n.mail-list {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  background: var(--bg-surface, var(--bg-base));\n  border-right: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n}\n\n.mail-list-head {\n  padding: 12px 14px 8px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  flex-shrink: 0;\n}\n\n.mail-list-head-title {\n  font-size: 0.9rem;\n  font-weight: 600;\n  color: var(--fg);\n  line-height: 1.3;\n}\n\n.mail-list-head-meta {\n  font-family: var(--font-mono, monospace);\n  font-size: 0.7rem;\n  color: var(--fg-faint, var(--fg-muted));\n  margin-top: 2px;\n}\n\n.mail-list-search {\n  padding: 8px 10px 6px;\n  flex-shrink: 0;\n}\n\n.mail-list-search-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  background: var(--bg-sunken, var(--bg-raised));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 6px;\n  padding: 0 8px;\n  height: 30px;\n  color: var(--fg-muted);\n}\n\n.mail-list-search-row .input {\n  flex: 1;\n  border: none;\n  background: transparent;\n  font-size: 0.8rem;\n  color: var(--fg);\n  outline: none;\n  padding: 0;\n}\n\n.mail-list-search-row .input::placeholder {\n  color: var(--fg-faint, var(--fg-muted));\n  font-style: italic;\n}\n\n.mail-list-section {\n  padding: 6px 14px 4px;\n  font-size: 0.7rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: var(--fg-faint, var(--fg-muted));\n  flex-shrink: 0;\n}\n\n/* Scrollable thread list area */\n.mail-list > :last-child {\n  overflow-y: auto;\n  flex: 1;\n}\n\n/* ── Mail row ── */\n.mail-row {\n  display: flex;\n  align-items: stretch;\n  cursor: pointer;\n  min-height: 68px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.04));\n  transition: background 120ms ease;\n  outline: none;\n}\n\n.mail-row:hover,\n.mail-row.is-selected {\n  background: var(--bg-raised);\n}\n\n.mail-row:focus-visible {\n  outline: 2px solid var(--primary);\n  outline-offset: -2px;\n}\n\n/* Left accent stripe — fills amber when unread or selected */\n.mail-row-tick {\n  width: 4px;\n  flex-shrink: 0;\n  background: transparent;\n  transition: background 120ms ease;\n}\n\n.mail-row.is-unread .mail-row-tick,\n.mail-row.is-selected .mail-row-tick {\n  background: var(--tint-fg-active, var(--tint-mail-fg, hsl(42,70%,62%)));\n}\n\n.mail-row-body {\n  flex: 1;\n  padding: 9px 10px 8px;\n  min-width: 0;\n}\n\n.mail-row-meta {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 6px;\n  margin-bottom: 2px;\n}\n\n.mail-row-from {\n  font-size: 0.82rem;\n  font-weight: 500;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  flex: 1;\n}\n\n.mail-row-time {\n  font-size: 0.72rem;\n  color: var(--fg-faint, var(--fg-muted));\n  white-space: nowrap;\n  flex-shrink: 0;\n}\n\n.mail-row-subject {\n  font-size: 0.82rem;\n  color: var(--fg-muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  margin-bottom: 2px;\n}\n\n.mail-row.is-unread .mail-row-subject {\n  color: var(--fg);\n  font-weight: 500;\n}\n\n.mail-row-preview {\n  font-size: 0.78rem;\n  color: var(--fg-faint, var(--fg-muted));\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.mail-row-tags {\n  display: flex;\n  gap: 4px;\n  flex-wrap: wrap;\n  margin-top: 4px;\n}\n\n/* ── Reader pane ── */\n.reader-pane {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  height: 100%;\n  background: var(--bg-base);\n}\n\n.reader-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  flex-shrink: 0;\n  background: var(--bg-surface, var(--bg-base));\n}\n\n.reader-toolbar-spacer {\n  flex: 1;\n}\n\n.reader-toolbar-meta {\n  font-size: 0.72rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-variant-numeric: tabular-nums;\n}\n\n.reader-body-wrap {\n  flex: 1;\n  overflow-y: auto;\n  padding: 16px 20px 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.reader-head {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.reader-from-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.reader-from-name {\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: var(--fg);\n  line-height: 1.25;\n}\n\n.reader-from-addr {\n  font-size: 0.76rem;\n  color: var(--fg-muted);\n  line-height: 1.3;\n}\n\n.reader-actions {\n  display: flex;\n  gap: 6px;\n  margin-left: auto;\n  flex-shrink: 0;\n}\n\n.reader-subject {\n  font-size: 1.05rem;\n  font-weight: 600;\n  color: var(--fg);\n  line-height: 1.35;\n  font-family: var(--font-display, var(--font-sans));\n}\n\n.reader-meta {\n  display: flex;\n  gap: 6px;\n  align-items: center;\n  flex-wrap: wrap;\n}\n\n.reader-body {\n  font-size: 0.875rem;\n  line-height: 1.65;\n  color: var(--fg);\n  font-family: var(--font-body, var(--font-sans));\n  max-width: 680px;\n}\n\n.reader-body p {\n  margin: 0 0 0.8em;\n}\n\n/* ── Quick reply ── */\n.reader-quick-reply {\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.1));\n  border-radius: 8px;\n  overflow: hidden;\n  background: var(--bg-raised);\n}\n\n.reader-quick-reply-head {\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  background: var(--bg-surface, var(--bg-base));\n}\n\n.reader-quick-reply-tag {\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n}\n\n.reader-quick-reply .input {\n  display: block;\n  width: 100%;\n  border: none;\n  border-radius: 0;\n  background: transparent;\n  padding: 10px 12px;\n  font-size: 0.85rem;\n  font-family: var(--font-body, var(--font-sans));\n  color: var(--fg);\n  line-height: 1.55;\n  resize: none;\n  outline: none;\n}\n\n.reader-quick-reply-foot {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 6px 12px 8px;\n  font-size: 0.72rem;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n/* ── Thread collapse rail ── */\n.thread-other {\n  margin: 8px 0;\n}\n\n.thread-collapse {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  cursor: pointer;\n  background: none;\n  border: none;\n  padding: 4px 0;\n  font-size: 0.78rem;\n  color: var(--fg-muted);\n  width: 100%;\n  text-align: left;\n}\n\n.thread-collapse-line {\n  flex: 1;\n  height: 1px;\n  background: var(--border-soft, rgba(0,0,0,0.08));\n}\n\n/* ── Workspace amber tint (applied when data-workspace=\"mail\") ── */\n/* The shell already sets --tint-mail-bg / --tint-mail-fg via @ikenga/tokens;\n * we just document the mapping here for reference.\n *   dark:  --tint-mail-bg = hsl(42,30%,11%); --tint-mail-fg = hsl(42,70%,62%)\n *   light: --tint-mail-bg = hsl(42,60%,92%); --tint-mail-fg = hsl(42,80%,28%)\n */\n[data-workspace=\"mail\"] {\n  --tint-bg-active: var(--tint-mail-bg, hsl(42, 30%, 11%));\n  --tint-fg-active: var(--tint-mail-fg, hsl(42, 70%, 62%));\n}\n\n/* Tag color overrides for mail domain tags */\n.tag.tag-deal   { --tag-color: var(--amber, hsl(42,80%,50%)); color: var(--tag-color); border-color: var(--tag-color); }\n.tag.tag-warn   { --tag-color: var(--danger, hsl(0,60%,55%)); color: var(--tag-color); border-color: var(--tag-color); }\n.tag.tag-system { --tag-color: var(--fg-muted); color: var(--tag-color); border-color: var(--tag-color); }\n.tag.tag-primary { --tag-color: var(--primary, hsl(220,70%,55%)); color: var(--tag-color); border-color: var(--tag-color); }\n\n/* dense-row--outbox modifier (Triage view) */\n.dense-row--outbox {\n  cursor: pointer;\n  padding-left: 0;\n}\n\n.dense-row--outbox:hover,\n.dense-row--outbox.is-on {\n  background: var(--bg-raised);\n}\n"
